{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.actual_production_size_split as with sku_eoq as ( select upper(trim(sku_group)) as sku_group, total_quant from snitch_db.maplemonk.gs_eoq_main_size_split_main_sheet qualify row_number() over (partition by upper(trim(sku_group)) order by sno) = 1 ), size_level_split as ( select a.sku_group, ifnull((total_quant*xs_split)::int,0) as xs_order_quant, ifnull((total_quant*s_split)::int,0) as s_order_quant, ifnull((total_quant*m_split)::int,0) as m_order_quant, ifnull((total_quant*l_split)::int,0) as l_order_quant, ifnull((total_quant*xl_split)::int,0) as xl_order_quant, ifnull((total_quant*xxl_split)::int,0) as xxl_order_quant from sku_eoq a left join snitch_db.maplemonk.final_output_eoq b on a.sku_group = b.sku_group ), current_inv_pre as ( select sku_group, ifnull(sum(case when SIZE = \'XS\' OR SIZE = \'28\' then total_inventory end),0) as xs_inv, ifnull(sum(case WHEN SIZE = \'S\' OR SIZE = \'30\' then total_inventory end),0) as s_inv, ifnull(sum(case WHEN SIZE = \'M\' OR SIZE = \'32\' then total_inventory end),0) as m_inv, ifnull(sum(case WHEN SIZE = \'L\' OR SIZE = \'34\' then total_inventory end),0) as l_inv, ifnull(sum(case WHEN SIZE = \'XL\' OR SIZE = \'36\' then total_inventory end),0) as xl_inv, ifnull(sum(case when SIZE IN (\'XXL\', \'XXl\', \'2XL\', \'38\') then total_inventory end),0) as xxl_inv from snitch_db.maplemonk.cut_size_analysis where date = current_date-1 and sku_group in (select sku_group from size_level_split) group by 1 union all select upper(trim(sku_group)) as sku_group, ifnull(sum(xs_units),0) as xs_inv, ifnull(sum(s_units),0) as s_inv, ifnull(sum(m_units),0) as m_inv, ifnull(sum(l_units),0) as l_inv, ifnull(sum(xl_units),0) as xl_inv, ifnull(sum(xxl_units),0) as xxl_inv from snitch_db.maplemonk.offline_master where upper(trim(sku_group)) in (select sku_group from size_level_split) group by 1 ), current_inv as ( select sku_group, sum(xs_inv) as xs_inv, sum(s_inv) as s_inv, sum(m_inv) as m_inv, sum(l_inv) as l_inv, sum(xl_inv) as xl_inv, sum(xxl_inv) as xxl_inv from current_inv_pre group by 1 ), sales as ( select sku_group, (ifnull(sum(case when size = \'XS\' then gross_quantity end),0)/30)::int as xs_ros, (ifnull(sum(case when size = \'S\' then gross_quantity end),0)/30)::int as s_ros, (ifnull(sum(case when size = \'M\' then gross_quantity end),0)/30)::int as m_ros, (ifnull(sum(case when size = \'L\' then gross_quantity end),0)/30)::int as l_ros, (ifnull(sum(case when size = \'XL\' then gross_quantity end),0)/30)::int as xl_ros, (ifnull(sum(case when size = \'XXL\' then gross_quantity end),0)/30)::int as xxl_ros from snitch_db.maplemonk.horizontal_sales_categories where upper(trim(sku_group)) in (select sku_group from size_level_split) and date >= current_date-30 group by 1 ), days_remaining as ( select sku_group, days_remaining from snitch_db.maplemonk.repeat_order_quant_eoq ), total_sales as ( select a.sku_group, xs_ros*b.days_remaining as xs_quant, s_ros*b.days_remaining as s_quant, m_ros*b.days_remaining as m_quant, l_ros*b.days_remaining as l_quant, xl_ros*b.days_remaining as xl_quant, xxl_ros*b.days_remaining as xxl_quant from sales a left join days_remaining b on a.sku_group = b.sku_group ), inv_subtraction as ( select a.sku_group, coalesce(greatest(xs_inv-xs_quant,0),0) as xs_remaining, coalesce(greatest(s_inv-s_quant,0),0) as s_remaining, coalesce(greatest(m_inv-m_quant,0),0) as m_remaining, coalesce(greatest(l_inv-l_quant,0),0) as l_remaining, coalesce(greatest(xl_inv-xl_quant,0),0) as xl_remaining from current_inv a left join total_sales b on a.sku_group = b.sku_group ), pre_main_check as ( select a.sku_group, coalesce(greatest(a.xs_order_quant-xs_remaining,0),0) as xs_order_quant, coalesce(greatest(a.s_order_quant-s_remaining,0),0) as s_order_quant, coalesce(greatest(a.m_order_quant-m_remaining,0),0) as m_order_quant, coalesce(greatest(a.l_order_quant-l_remaining,0),0) as l_order_quant, coalesce(greatest(a.xl_order_quant-xl_remaining,0),0) as xl_order_quant, coalesce(greatest(a.xxl_order_quant-xs_remaining,0),0) as xxl_order_quant from size_level_split a left join inv_subtraction b on a.sku_group = b.sku_group ) select sku_group, xs_order_quant, case when sku_group like \'4MSS1813%\' and sku_group in (select sku_group from current_inv where xxl_inv >= 100) then (s_order_quant + xxl_order_quant/4)::int else s_order_quant end as s_order_quant, case when sku_group like \'4MSS1813%\' and sku_group in (select sku_group from current_inv where xxl_inv >= 100) then (m_order_quant + xxl_order_quant/4)::int else m_order_quant end as m_order_quant, case when sku_group like \'4MSS1813%\' and sku_group in (select sku_group from current_inv where xxl_inv >= 100)then (l_order_quant + xxl_order_quant/4)::int else l_order_quant end as l_order_quant, case when sku_group like \'4MSS1813%\' and sku_group in (select sku_group from current_inv where xxl_inv >= 100) then (xl_order_quant + xxl_order_quant/4)::int else m_order_quant end as xl_order_quant, case when sku_group like \'4MSS1813%\' and sku_group in (select sku_group from current_inv where xxl_inv >= 100) then 0 else xxl_order_quant end as xxl_order_quant, from pre_main_check",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            